-- Verified installed native wells and ordinary light switches; other object classes remain unchanged.
CREATE TABLE environment_interaction_definitions (
 map_id INTEGER NOT NULL, object_id BIGINT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('well','light')),
 template_id INTEGER NOT NULL, x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,
 initial_state SMALLINT NOT NULL CHECK(initial_state IN (0,1)),state_payload_hex TEXT NOT NULL,
 duration_ms INTEGER NOT NULL CHECK(duration_ms>=0),item_reference INTEGER,quantity INTEGER,
 requires_nonhero BOOLEAN NOT NULL DEFAULT FALSE,on_timeout_ms INTEGER NOT NULL DEFAULT 0,off_timeout_ms INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(map_id,object_id),CHECK(kind<>'well' OR (item_reference>0 AND quantity>0 AND duration_ms>0))
);
CREATE TABLE environment_interaction_tickets (
 token UUID PRIMARY KEY,account_id BIGINT NOT NULL, generation TEXT NOT NULL,character_id BIGINT NOT NULL,
 map_id INTEGER NOT NULL,object_id BIGINT NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,
 due_at TIMESTAMPTZ NOT NULL,is_hero BOOLEAN,state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','completed','cancelled')),
 FOREIGN KEY(map_id,object_id) REFERENCES environment_interaction_definitions(map_id,object_id)
);
CREATE UNIQUE INDEX environment_interaction_one_active ON environment_interaction_tickets(character_id) WHERE state='active';
CREATE TABLE environment_interaction_states (
 map_id INTEGER NOT NULL,object_id BIGINT NOT NULL,state SMALLINT NOT NULL CHECK(state IN (0,1)),expires_at TIMESTAMPTZ,
 PRIMARY KEY(map_id,object_id),FOREIGN KEY(map_id,object_id) REFERENCES environment_interaction_definitions(map_id,object_id)
);
